# ==============================================================================# 082_CAPABILITY_ADAPTER_MANAGER.py## IOTEC CAPABILITY ADAPTER MANAGER## Missão:# Gerenciar todos os adaptadores de capacidades do IOTEC.## Não executa integrações diretamente.# Apenas registra, habilita, desabilita e monitora adaptadores.# ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class CapabilityAdapterManager:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS capability_adapters(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            adapter_id TEXT,            capability TEXT,            adapter_name TEXT,            version TEXT,            provider TEXT,            status TEXT,            health_status TEXT,            execution_count INTEGER,            last_execution TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _hash(self, payload):        raw = json.dumps(            payload,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def register_adapter(        self,        capability,        adapter_name,        version,        provider,        metadata=None    ):        metadata = metadata or {}        timestamp = datetime.utcnow().isoformat()        adapter_id = hashlib.md5(            f"{timestamp}{adapter_name}".encode()        ).hexdigest()        payload = {            "timestamp": timestamp,            "adapter_id": adapter_id,            "capability": capability,            "adapter_name": adapter_name,            "version": version,            "provider": provider,            "status": "REGISTERED",            "health_status": "UNKNOWN",            "execution_count": 0,            "last_execution": None,            "metadata": metadata        }        signature = self._hash(payload)        self.conn.execute("""        INSERT INTO capability_adapters(            timestamp,            adapter_id,            capability,            adapter_name,            version,            provider,            status,            health_status,            execution_count,            last_execution,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?)        """, (            payload["timestamp"],            payload["adapter_id"],            payload["capability"],            payload["adapter_name"],            payload["version"],            payload["provider"],            payload["status"],            payload["health_status"],            payload["execution_count"],            payload["last_execution"],            json.dumps(payload["metadata"], ensure_ascii=False),            signature        ))        self.conn.commit()        payload["hash"] = signature        return payload# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    manager = CapabilityAdapterManager()    adapter = manager.register_adapter(        capability="BASE_EMPRESARIAL",        adapter_name="EMPRESARIAL_ADAPTER",        version="1.0.0",        provider="PENDENTE",        metadata={            "origin":"081_INTEGRATION_EXECUTION_ENGINE",            "status":"AGUARDANDO_IMPLEMENTAÇÃO"        }    )    print("="*80)    print("CAPABILITY ADAPTER")    print("="*80)    for k,v in adapter.items():        print(f"{k:22}: {v}")    print("="*80)